    reviews = inputs["reviews"]
    labels = readings["topic"]
    counts = {topic: 0 for topic in topics}
    sums = {topic: 0 for topic in topics}

    for review, topic in zip(reviews, labels):
        counts[topic] += 1
        sums[topic] += review["stars"]

    active = [topic for topic in topics if counts[topic] > 0]
    if active:
        worst = min(active, key=lambda topic: (sums[topic] / counts[topic], topics.index(topic)))
    else:
        worst = "none"

    if counts["quality"]:
        tenths = (20 * sums["quality"] + counts["quality"]) // (2 * counts["quality"])
        quality_stars = str(tenths // 10) + "." + str(tenths % 10)
    else:
        quality_stars = "none"

    return "price " + str(counts["price"]) + ", quality " + str(counts["quality"]) + ", delivery " + str(counts["delivery"]) + ", service " + str(counts["service"]) + " | worst " + worst + " | quality stars " + quality_stars

