import re

def solve(inputs, readings):
    def parse_json(text):
        pos = 0

        def whitespace():
            nonlocal pos
            while pos < len(text) and text[pos] in ' \t\r\n':
                pos += 1

        def parse_string():
            nonlocal pos
            pos += 1
            chars = []
            escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
            while pos < len(text):
                char = text[pos]
                pos += 1
                if char == '"':
                    return ''.join(chars)
                if char == '\\':
                    code = text[pos]
                    pos += 1
                    if code == 'u':
                        chars.append(chr(int(text[pos:pos + 4], 16)))
                        pos += 4
                    else:
                        chars.append(escapes[code])
                else:
                    chars.append(char)
            raise ValueError('Unterminated JSON string')

        def parse_value():
            nonlocal pos
            whitespace()
            if pos >= len(text):
                raise ValueError('Unexpected end of JSON')
            char = text[pos]
            if char == '"':
                return parse_string()
            if char == '[':
                pos += 1
                result = []
                whitespace()
                if pos < len(text) and text[pos] == ']':
                    pos += 1
                    return result
                while True:
                    result.append(parse_value())
                    whitespace()
                    if text[pos] == ']':
                        pos += 1
                        return result
                    if text[pos] != ',':
                        raise ValueError('Expected comma in JSON array')
                    pos += 1
            if char == '{':
                pos += 1
                result = {}
                whitespace()
                if pos < len(text) and text[pos] == '}':
                    pos += 1
                    return result
                while True:
                    whitespace()
                    if text[pos] != '"':
                        raise ValueError('Expected JSON object key')
                    key = parse_string()
                    whitespace()
                    if text[pos] != ':':
                        raise ValueError('Expected colon in JSON object')
                    pos += 1
                    result[key] = parse_value()
                    whitespace()
                    if text[pos] == '}':
                        pos += 1
                        return result
                    if text[pos] != ',':
                        raise ValueError('Expected comma in JSON object')
                    pos += 1
            if text.startswith('true', pos):
                pos += 4
                return True
            if text.startswith('false', pos):
                pos += 5
                return False
            if text.startswith('null', pos):
                pos += 4
                return None
            match = re.match(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?', text[pos:])
            if match:
                token = match.group(0)
                pos += len(token)
                return float(token) if any(c in token for c in '.eE') else int(token)
            raise ValueError('Invalid JSON value')

        result = parse_value()
        whitespace()
        if pos != len(text):
            raise ValueError('Extra text after JSON value')
        return result

    def to_cents(amount):
        value = str(amount).strip()
        negative = value.startswith('-')
        if value[:1] in '+-':
            value = value[1:]
        parts = value.split('.', 1)
        whole = int(parts[0] or '0')
        fraction = (parts[1] if len(parts) > 1 else '').ljust(2, '0')[:2]
        cents = whole * 100 + int(fraction or '0')
        return -cents if negative else cents

    def format_cents(value):
        sign = '-' if value < 0 else ''
        value = abs(value)
        return sign + str(value // 100) + '.' + str(value % 100).zfill(2)

    lines = inputs['lines']
    if isinstance(lines, str):
        lines = parse_json(lines)
    categories = readings['category']
    totals = {'travel': 0, 'meals': 0, 'equipment': 0, 'other': 0}
    flagged = 0
    for line, category in zip(lines, categories):
        amount = to_cents(line['amount'])
        totals[category] += amount
        if (category == 'meals' and amount > 5000) or (category == 'equipment' and amount > 50000):
            flagged += 1
    return 'travel ' + format_cents(totals['travel']) + ' | meals ' + format_cents(totals['meals']) + ' | equipment ' + format_cents(totals['equipment']) + ' | other ' + format_cents(totals['other']) + ' | ' + str(flagged) + ' flagged'

