import re

def solve(inputs, readings):
    drops = inputs['drops']
    if isinstance(drops, str):
        pattern = r'"(?:\\.|[^"\\])*"|[{}\[\]:,]|-?\d+(?:\.\d+)?|true|false|null'
        tokens = re.findall(pattern, drops)

        def decode_string(token):
            escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
            def replace(match):
                value = match.group(1)
                if value.startswith('u'):
                    return chr(int(value[1:], 16))
                return escapes[value]
            return re.sub(r'\\(u[0-9a-fA-F]{4}|["\\/bfnrt])', replace, token[1:-1])

        def read_value(pos):
            token = tokens[pos]
            if token == '[':
                result = []
                pos += 1
                if tokens[pos] == ']':
                    return result, pos + 1
                while True:
                    value, pos = read_value(pos)
                    result.append(value)
                    if tokens[pos] == ']':
                        return result, pos + 1
                    pos += 1
            if token == '{':
                result = {}
                pos += 1
                if tokens[pos] == '}':
                    return result, pos + 1
                while True:
                    key = decode_string(tokens[pos])
                    pos += 2
                    value, pos = read_value(pos)
                    result[key] = value
                    if tokens[pos] == '}':
                        return result, pos + 1
                    pos += 1
            if token.startswith('"'):
                return decode_string(token), pos + 1
            if token == 'true':
                return True, pos + 1
            if token == 'false':
                return False, pos + 1
            if token == 'null':
                return None, pos + 1
            if '.' in token:
                return float(token), pos + 1
            return int(token), pos + 1

        drops, end = read_value(0)

    outcomes = readings['outcomes']
    scores = {}
    delivered = 0
    missed = 0
    damaged = 0

    for drop, outcome in zip(drops, outcomes):
        driver = drop['driver']
        if driver not in scores:
            scores[driver] = 0
        if outcome == 'delivered':
            delivered += 1
            scores[driver] += 2 if drop['minutes_late'] <= 10 else 1
        elif outcome == 'missed':
            missed += 1
        else:
            damaged += 1
            scores[driver] -= 1

    best = sorted(scores, key=lambda driver: (-scores[driver], driver))[0]
    return f'{delivered} delivered, {missed} missed, {damaged} damaged | best {best} ({scores[best]})'

